-- About text for every oil, rewritten 20 Nov 2026 (owner): one consistent, polished story per oil.
-- Each one: seed + sourcing → traditional Kolhu (kachi ghani) pressing → 10-day gravity sedimentation → uses.
-- Only facts already on the site are used (sourcing where known). Previous text: backup_20261120_products.
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Groundnut Oil</strong> is made from desi groundnuts sourced directly from farmers.</p><p>Made the traditional way, the shelled kernels are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>With its rich aroma and natural nutty taste, it is ideal for deep frying, roasting and everyday Indian cooking.</p>' WHERE handle = 'groundnut-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Yellow Mustard Oil</strong> is made from carefully selected desi yellow mustard seeds sourced directly from farmers.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Milder than black mustard oil, it still carries the familiar <strong>sarson ki jhaal</strong> loved in Indian kitchens. Perfect for tadka, sautéing, frying and achaar.</p>' WHERE handle = 'yellow-mustard-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Black Mustard Oil</strong> is the sharp, eye-watering kachi ghani sarson ka tel, made from black mustard seeds for a bold, pungent flavour.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Its strong aroma makes it the traditional choice for achaar, tadka and Bengali-style cooking, and for a warming winter body malish.</p>' WHERE handle = 'black-mustard-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed White Sesame Oil</strong> is made from desi white til grown by farmers in Marwar, Rajasthan.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Light and golden with a mild til flavour, it suits everyday cooking, South Indian dishes, chutneys and dressings, and is also used for body massage.</p>' WHERE handle = 'white-sesame-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Brown Sesame Oil</strong> is made from desi brown til, the <strong>Marwari seed</strong> grown by farmers in Marwar, Rajasthan.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Its warm, toasty aroma brings depth to daily cooking, pickles and til sweets, and makes it a traditional choice for winter malish.</p>' WHERE handle = 'brown-sesame-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Black Sesame Oil</strong> is made from jet-black til <strong>sourced from Gujarat</strong>, the most valued til for wellness.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Deep in colour and aroma, it is traditionally used for abhyanga (self-massage), oil pulling and hair care.</p>' WHERE handle = 'black-sesame-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Coconut Oil</strong> is made from carefully selected, sulphur-free coconuts from Tiptur, Karnataka.</p><p>Made the traditional way, the dried coconut are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>With its rich coconut aroma and authentic flavour, it is perfect for South Indian cooking, sautéing and baking, and for everyday hair and skin care.</p>' WHERE handle = 'coconut-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Sunflower Oil</strong> is made from clean, carefully selected sunflower seeds.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Light in taste and colour, it lets the food''s own flavour come through. Ideal for everyday sabzi, dal, parathas and baking.</p>' WHERE handle = 'sunflower-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Almond Oil (badam rogan)</strong> is made from carefully selected almonds.</p><p>Made the traditional way, the almonds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural Vitamin E, light texture and mild aroma.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Light and non-sticky, it absorbs easily into skin and hair and is gentle enough for baby malish. Traditionally, a few drops are also added to warm milk.</p>' WHERE handle = 'almond-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Walnut Oil (akhrot tel)</strong> is pressed in small batches from quality walnuts.</p><p>Made the traditional way, the kernels are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>With its rich, nutty aroma, it is used for skin and hair care, or drizzled over salads and finished dishes. Do not heat.</p>' WHERE handle = 'walnut-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Flaxseed Oil (alsi tel)</strong> is made from clean, carefully selected flaxseeds, a natural plant source of Omega-3.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Best used raw: take a teaspoon a day, or drizzle over salads, raita and roti after cooking. Do not heat or fry, and refrigerate after opening.</p>' WHERE handle = 'flaxseed-oil';
UPDATE products SET description_html = '<p>Our <strong>Wood-Pressed Castor Oil (arandi tel)</strong> is made from clean, carefully selected castor seeds.</p><p>Made the traditional way, the seeds are cleaned by hand and pressed slowly in a wooden <strong>Kolhu (kachi ghani)</strong>. The press turns at a low speed, so the oil stays cool and keeps its natural aroma, colour and nutrients.</p><p>The fresh oil is then cloth-filtered and left to rest for <strong>10 days of natural gravity sedimentation</strong>. Heavier particles settle on their own, with no chemical refining, bleaching or high-pressure filtration, so what reaches you is pure, unrefined oil.</p><p>Thick and rich, it is used for hair, brows and lashes, dry skin and traditional joint massage. For external use only.</p>' WHERE handle = 'castor-oil';
